let navGrid;function navigationGrid(){if(navGrid)return navGrid;navGrid=new Uint8Array(91*91);for(let z=0;z<91;z++)for(let x=0;x<91;x++)navGrid[z*91+x]=blocked(x*2-90,z*2-90,.45)?1:0;return navGrid;}
