function tickAI(dt){for(const a of actors){if(a.remote)continue;if(a.hp<=0){if(a.team==='enemy')continue;a.dead-=dt;if(a.dead<=0){a.hp=100;a.g.rotation.set(0,0,0);a.g.position.set((a.index-1)*4,0,65);a.cool=3;}else continue;}const p=a.g.position;const eye=p.clone().add(new THREE.Vector3(0,1.42,0));a.senseTimer=(a.senseTimer||0)-dt;if(a.senseTimer<=0){a.senseTimer=.13+rand()*.05;const targets=a.team==='ally'?actors.filter(t=>t.team==='enemy'&&t.hp>0).map(t=>({pos:t.g.position,a:t})): [{pos:player,a:null},...actors.filter(t=>t.team==='ally'&&t.hp>0&&t.g.visible).map(t=>({pos:t.g.position,a:t}))];targets.sort((u,v)=>p.distanceTo(u.pos)-p.distanceTo(v.pos));a.seen=null;for(const t of targets.slice(0,3)){if(p.distanceTo(t.pos)<48&&visible(eye,t.pos.clone().add(new THREE.Vector3(0,t.a?1.25:crouch?.75:1.4,0)))){a.seen=t;break;}}}let enemy=a.seen;if(enemy?.a&&enemy.a.hp<=0)enemy=null;let dest;if(a.team==='ally'){if(order==='hold')dest=a.hold||p;else if(order==='follow')dest=player.clone().add(new THREE.Vector3((a.index-1)*3,0,3+a.index));else dest=objectivePoint().clone().add(new THREE.Vector3((a.index-1)*3,0,4+a.index*2));}else{a.home??=p.clone();a.patrolTimer=(a.patrolTimer||0)-dt;if(a.patrolTimer<=0&&!enemy){const candidate=a.home.clone().add(new THREE.Vector3(range(-4,4),0,range(-4,4)));if(!blocked(candidate.x,candidate.z,.6))a.patrol=candidate;a.patrolTimer=6+rand()*5;}dest=a.patrol||a.home;if(enemy){dest=p;a.route=[];}}
 a.routeTime=(a.routeTime||0)-dt;if(a.routeTime<=0&&!enemy){a.route=pathTo(p,dest);a.routeTime=2+rand();}while(a.route?.length&&Math.hypot(a.route[0].x-p.x,a.route[0].z-p.z)<.9)a.route.shift();const waypoint=a.route?.length?a.route[0]:dest,speed=enemy?.45:a.team==='ally'?3:1.6,diff=waypoint.clone().sub(p);diff.y=0;let moved=0;if(diff.length()>(a.route?.length?.4:2)){diff.normalize();moved=move(p,diff.x*speed*dt,diff.z*speed*dt);if(moved<speed*dt*.2){a.stuck+=dt;const side=a.index%2?1:-1;move(p,Math.cos(a.phase+a.stuck*.4)*speed*dt*side,Math.sin(a.phase+a.stuck*.4)*speed*dt);}else a.stuck=0;}
 p.y=groundY(p.x,p.z);const look=enemy?enemy.pos:dest;a.g.rotation.y=Math.atan2(p.x-look.x,p.z-look.z);a.speed=moved/Math.max(.001,dt);a.cool-=dt;if(enemy&&a.cool<=0){a.cool=.65+rand()*.95;const endpoint=enemy.pos.clone().add(new THREE.Vector3(0,enemy.a?1.25:crouch?.75:1.4,0));tracer(eye,endpoint,a.team==='ally'?0xffdf9e:0xffb575);if(p.distanceTo(player)<35)sound('shot',.12);let chance=enemy.a?.42:.22;const distance=p.distanceTo(enemy.pos);chance*=Math.max(.4,1-distance/90);if(crouch&&!enemy.a)chance*=.65;if(rand()<chance&&aiHit(enemy,eye,endpoint))return;}}}
// Bot hits have no ray: they strike the chest along the shooter-to-target line and never count as headshots.
function aiHit(enemy,eye,endpoint){const dir=endpoint.clone().sub(eye).normalize();if(enemy.a){const amount=enemy.a.remote?(14+rand()*10)*CLASSES[remoteClass].armor:24;enemy.a.hp-=amount;if(enemy.a.remote)enemy.a.healing=0;const kill=enemy.a.hp<=0;if(kill)enemy.a.dead=15;characterHit(enemy.a,endpoint,dir,false,kill);if(kill&&enemy.a.remote){finish(false);return true;}}else{hp-=(rand()*10+12)*current().armor;damage=.7;healing=0;sound('hit');characterHit(null,endpoint,dir,false,hp<=0);if(hp<=0){hp=0;finish(false);return true;}}return false;}
function drawMap(){const c=$('map').getContext('2d');c.clearRect(0,0,170,170);c.save();c.translate(85,85);c.strokeStyle='#b6b5a329';for(let r of [28,56,82]){c.beginPath();c.arc(0,0,r,0,7);c.stroke();}const scale=.85;for(const s of solids){c.fillStyle='#c8b68a66';c.fillRect((s.x-player.x)*scale-s.w*scale,(s.z-player.z)*scale-s.d*scale,s.w*2*scale,s.d*2*scale);}const goal=objectivePoint();c.fillStyle='#dcbd7f';c.beginPath();c.arc((goal.x-player.x)*scale,(goal.z-player.z)*scale,5,0,7);c.fill();for(const a of actors){if(a.hp<=0||!a.g.visible||a.team==='enemy')continue;c.fillStyle=a.remote?'#e7e9cb':'#90d9d0';c.beginPath();c.arc((a.g.position.x-player.x)*scale,(a.g.position.z-player.z)*scale,2.5,0,7);c.fill();}c.rotate(-yaw);c.fillStyle='#fff';c.beginPath();c.moveTo(0,-6);c.lineTo(-4,4);c.lineTo(4,4);c.fill();c.restore();}
function missionTick(dt){const dist=player.distanceTo(objectivePoint());if(mode!=='skirmish'&&stage===0){$('interact').textContent=player.distanceTo(intel)<5?'E · RECOVER ROUTE LOG':'';}else{$('interact').textContent='';}if(mode==='skirmish'||stage===1){const friends=(player.distanceTo(target)<9?1:0)+(remote.g.visible&&remote.g.position.distanceTo(target)<9?1:0);const enemies=actors.filter(a=>a.team==='enemy'&&a.hp>0&&a.g.position.distanceTo(target)<15).length;const required=mode==='skirmish'?45:25;if(friends>0&&enemies===0)progress=Math.min(required,progress+dt);if(progress>=required){if(mode==='skirmish')finish(true);else{stage=2;progress=0;radio('Command: Signal restored. Convoy has diverted to safety. Viper, move to the eastern courtyard for extraction.');}}}else if(stage===2){if(player.distanceTo(extract)<5&&(mode!=='coop'||remote.g.position.distanceTo(extract)<5)){progress+=dt;if(progress>=5)finish(true);}else progress=0;}}
function hudObjective(dist){const required=mode==='skirmish'?45:stage===1?25:5;$('objective-label').textContent=mode==='skirmish'?'SECURE THE RELAY':`${String(stage+1).padStart(2,'0')} / BROKEN SIGNAL`;$('objtext').textContent=mode==='skirmish'||stage===1?'Restore and hold the relay':stage===0?'Recover the route log':'Reach the extraction courtyard';$('distance').textContent=`${Math.round(dist)} M · ${mode==='skirmish'||stage===1?`${Math.floor(progress)} / ${required} SEC`:stage===0?'WESTERN FIELD OFFICE':mode==='coop'?'BOTH PLAYERS REQUIRED':'HOLD FOR EXTRACTION'}`;$('capture').style.width=(stage===0&&mode!=='skirmish'?0:progress/required*100)+'%';ringmesh.visible=mode==='skirmish'||stage===1;extractionMark.visible=mode!=='skirmish'&&stage===2;intelObject.visible=mode!=='skirmish'&&stage===0;}
